    QQuickItem *item = findWidget(id);
    if (!item) {
        return 0;
    }
    QObject *anchors = item->property("anchors").value<QObject *>();
    if (!anchors) {
        return 0;
    }
    QVariant fill = anchors->property("fill");
    QQuickItem *target = fill.value<QQuickItem *>();
    return target == g.root ? 1 : 0;
}

