+fn tokens() -> Scenario {
+    let mut b = Builder::new();
+    b.create(1, component_type::VSTACK);
+    b.create(2, component_type::TEXT);
+    b.create(3, component_type::TEXT);
+    b.create(4, component_type::TEXT);
+    b.create(5, component_type::BUTTON);
+    b.insert(1, 2);
+    b.insert(1, 3);
+    b.insert(1, 4);
+    b.insert(1, 5);
