         assert!(!is_custom_chrome(&node), "missing NAV_CHROME → PlatformDefault");
         // Custom = enum code 1 carried as an F32 bit pattern (spec convention).
         node.properties.insert(property_id::NAV_CHROME, 1.0f32.to_bits());
