             let mut host = Host::new(&mut mem, &layout);
             tree.apply_frame(&host.frames()[0]);
         }

         let root = tree.root().unwrap().clone();
         let l = crate::layout::stack_layout(&root).unwrap();
         assert_eq!(l.spacing, 12);
         assert_eq!(l.child_align, Align::End);
     }

