     fn generative_space_ref_renders_calc() {
         let strings = string_section(&["space.2"]);
         let opcodes = vec![
             Opcode::new(category::TREE, tree::CREATE_NODE, 0, 1, component_type::VSTACK as u32, 0),
             Opcode::new(
                 category::STYLE,
                 style::SET_PROPERTY,
