     #[test]
     fn text_builds_plain_node() {
         let node = Text::new("ab").build();
         assert_eq!(node.id, 0);
         assert_eq!(node.component, Component::Text { text: "ab".into() });
         assert!(node.properties.is_empty());
         assert!(node.children.is_empty());
