}

package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.state.State;

import static com.pathland.view.signal.Signals.computed;

/**
 * A single track row: a cover thumbnail, the title/artist, and the duration.
 * Selecting it starts that track through the app-owned player state, and the
 * current row is highlighted reactively via a computed background/foreground.
 */
public final class TrackRowView implements View {

    private final Track track;
    private final int index;
    private final State<Integer> trackIndex;
    private final State<Float> position;
    private final State<Boolean> playing;

    /**
     * @param track      the track this row represents
     * @param index      the track's index in the library
     * @param trackIndex the current track index (drives the highlight)
     * @param position   the play position (seconds), reset on selection
     * @param playing    set to true when the row is selected
     */
    public TrackRowView(Track track, int index, State<Integer> trackIndex,
                        State<Float> position, State<Boolean> playing) {
        this.track = track;
        this.index = index;
        this.trackIndex = trackIndex;
        this.position = position;
        this.playing = playing;
    }

    @Override
    public View body() {
        var isCurrent = computed(() -> MusicPlayerView.at(trackIndex.get()) == track);
        var bg = computed(() -> isCurrent.get() ? MusicPlayerView.ACTIVE_ROW_BG : Color.CLEAR);
        var fg = computed(() -> isCurrent.get() ? MusicPlayerView.ACTIVE_ROW_FG : Color.BLACK);
        return Button.of(
                HStack.of(Alignment.CENTER, 12f,
                        Image.of(track.cover()).with(FrameMod.of(44, 44), ScaledToFit.of()),
                        VStack.of(Alignment.LEADING, 2,
                                Text.of(track.title()).with(FontWeightMod.of(FontWeight.SEMIBOLD)),
                                Text.of(track.artist() + " · " + track.album())
                                        .with(FontSize.of(13),
                                                ForegroundStyle.of(MusicPlayerView.SECONDARY_FG))
                        ),
                        Spacer.of(),
                        Text.of(MusicPlayerView.fmt(track.duration()))
                                .with(FontSize.of(13), ForegroundStyle.of(MusicPlayerView.SECONDARY_FG))
                ),
                () -> {
                    trackIndex.set(index);
                    position.set(0f);
                    playing.set(true);
                })
                .with(Background.of(bg), ForegroundStyle.of(fg))
                .with(Padding.of(6));
    }
}

package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.state.State;

import static com.pathland.view.signal.Signals.computed;

/**
 * The now-playing sidebar (right): the current track's large album art, its
 * title/artist, and the next two tracks. Everything is bound to the current
 * {@code trackIndex}, so a track change re-emits only this pane's deltas.
 */
public final class NowPlayingSidebar implements View {

    private final State<Integer> trackIndex;

    /**
     * @param trackIndex the current track index (drives the art + up-next)
     */
    public NowPlayingSidebar(State<Integer> trackIndex) {
        this.trackIndex = trackIndex;
    }

    @Override
    public View body() {
        return VStack.of(Alignment.LEADING, 14,
                Text.of("Now Playing").with(FontSize.of(18), FontWeightMod.of(FontWeight.BOLD))
                        .with(AccessibilityRole.of(Roles.HEADER)),
                Image.of(computed(() -> MusicPlayerView.at(trackIndex.get()).cover()))
                        .with(FrameMod.of(220, 220), ScaledToFit.of())
                        .with(Padding.of(0, 0, 0, 6)),
                Text.of(computed(() -> MusicPlayerView.at(trackIndex.get()).title()))
                        .with(FontSize.of(20), FontWeightMod.of(FontWeight.BOLD)),
                Text.of(computed(() -> MusicPlayerView.at(trackIndex.get()).artist()
                        + " · " + MusicPlayerView.at(trackIndex.get()).album()))
                        .with(ForegroundStyle.of(MusicPlayerView.SECONDARY_FG)),
                Divider.of().with(Padding.of(0, 0, 0, 10)),
                Text.of("Up Next").with(FontWeightMod.of(FontWeight.SEMIBOLD)),
                upNextRow(1),
                upNextRow(2)
        )
        .with(Padding.of(24))
        .with(Background.of(MusicPlayerView.SIDEBAR_BG))
        .with(FrameMod.of(MusicPlayerView.SIDEBAR_WIDTH, Commands.Size.FILL));
    }

    /** The track {@code offset} places after the current one. */
    private View upNextRow(int offset) {
        return Text.of(computed(() -> {
            Track t = MusicPlayerView.at(trackIndex.get() + offset);
            return (offset == 1 ? "Up next · " : "Then · ") + t.title() + " — " + t.artist();
        })).with(FontSize.of(13), ForegroundStyle.of(MusicPlayerView.SECONDARY_FG));
    }
}

package com.pathland.demo.music;

import com.pathland.view.*;
import com.pathland.view.state.State;

import static com.pathland.view.signal.Signals.computed;

/**
 * The bottom player bar: transport controls (prev / play-pause / next), the
 * now-playing title and artist, a draggable seek slider with elapsed/duration
 * labels, and a volume slider. Playback is app-owned state — the seek slider is
 * user-draggable; position does not auto-advance.
 */
public final class PlayerBar implements View {

    private final State<Integer> trackIndex;
    private final State<Float> position;
    private final State<Boolean> playing;
    private final State<Float> volume;

    /**
     * @param trackIndex the current track index (drives the title/artist)
     * @param position   the play position (seconds), bound to the seek slider
     * @param playing    toggled by the play/pause button
     * @param volume     bound to the volume slider
     */
    public PlayerBar(State<Integer> trackIndex, State<Float> position,
                     State<Boolean> playing, State<Float> volume) {
        this.trackIndex = trackIndex;
        this.position = position;
        this.playing = playing;
        this.volume = volume;
    }

    @Override
    public View body() {
        var current = computed(() -> MusicPlayerView.at(trackIndex.get()));
        var elapsed = computed(() -> MusicPlayerView.fmt(position.get()));
        var duration = computed(() -> MusicPlayerView.fmt(current.get().duration()));
        var glyph = computed(() -> playing.get() ? "⏸" : "▶");

        return HStack.of(Alignment.CENTER, 14f,
                Button.of("⏮", this::prev).with(FontSize.of(20)),
                Button.of(Text.of(glyph), () -> playing.update(v -> !v)).with(FontSize.of(28)),
                Button.of("⏭", this::next).with(FontSize.of(20)),
                VStack.of(Alignment.LEADING, 2,
                        Text.of(computed(() -> current.get().title()))
                                .with(FontWeightMod.of(FontWeight.SEMIBOLD)),
                        Text.of(computed(() -> current.get().artist()))
                                .with(FontSize.of(13), ForegroundStyle.of(MusicPlayerView.SECONDARY_FG))
                ).with(Padding.of(8, 20, 8, 20)).with(FrameMod.of(180f)),
                Spacer.of(),
                Text.of(elapsed).with(FontSize.of(13), ForegroundStyle.of(MusicPlayerView.SECONDARY_FG)),
                Slider.of(position.signal(), 0f, MusicPlayerView.SEEK_MAX).with(FrameMod.of(240f)),
                Text.of(duration).with(FontSize.of(13), ForegroundStyle.of(MusicPlayerView.SECONDARY_FG)),
                Spacer.of(),
                Text.of("🔊").with(FontSize.of(16)),
                Slider.of(volume.signal(), 0f, MusicPlayerView.VOLUME_MAX).with(FrameMod.of(96f))
        )
        .with(Padding.of(12, 16, 12, 16))
        .with(Background.of(MusicPlayerView.BAR_BG))
        .with(Border.of(MusicPlayerView.BAR_BORDER, 1f, 0f))
        .with(FrameMod.of(Commands.Size.FILL, MusicPlayerView.BAR_HEIGHT));
    }

    /** Previous track (wraps around) and restart from the top. */
    private void prev() {
        trackIndex.update(i -> (i - 1 + MusicPlayerView.TRACKS.size()) % MusicPlayerView.TRACKS.size());
        position.set(0f);
    }

    /** Next track (wraps around) and restart from the top. */
    private void next() {
        trackIndex.update(i -> (i + 1) % MusicPlayerView.TRACKS.size());
        position.set(0f);
    }
}

