import com.pathland.demo.music.MusicPlayerView;
import com.pathland.render.html.HtmlRenderer;
import com.pathland.view.*;
import com.pathland.view.emit.*;
import com.pathland.view.state.*;

public class RenderHtml {
  public static void main(String[] a) {
    StateStore store = new InMemoryStateStore();
    PersistentState state = new PersistentState(store, "s");
    FrameOpcodeSink sink = new FrameOpcodeSink();
    RenderResult r = new Emitter(sink).mount(new MusicPlayerView(), new Environment(state));
    if (!HtmlRenderer.isAvailable()) { System.out.println("NO RENDERER"); state.close(); return; }
    String html = HtmlRenderer.instance().render(sink.frame(), r.rootId());
    System.out.println("LEN=" + html.length());
    System.out.println("HAS_IMG=" + html.contains("albumart/cover1.svg"));
    System.out.println("IMG_COUNT=" + count(html, "<img"));
    System.out.println("SLIDER_COUNT=" + count(html, "type=\"range\""));
    System.out.println("BUTTON_COUNT=" + count(html, "<button"));
    System.out.println("HAS_PLAY=" + html.contains("⏮"));
    System.out.println("HAS_SEEK_RANGE=" + html.contains("max=\"240\""));
    System.out.println("HAS_VOLUME_RANGE=" + html.contains("max=\"100\""));
    System.out.println("HAS_LIBRARY=" + html.contains("Library"));
    System.out.println("HAS_NOWPLAYING=" + html.contains("Now Playing"));
    state.close();
  }
  static int count(String s, String sub) { int n=0,i=0; while((i=s.indexOf(sub,i))>=0){n++;i+=sub.length();} return n; }
}
