         String route = null;
         float width = -1f;
         float height = -1f;
         for (Opcode op : parsed.opcodes()) {
             if (op.category() != Categories.META || op.command() != Commands.Meta.ENVIRONMENT) {
                 continue;
             }
             switch (op.a() & 0xFFFF) {
                 case Commands.Environment.VIEWPORT_WIDTH ->
