package com.pathland.view;

import com.pathland.view.signal.WritableSignal;

/**
 * An audio style (SwiftUI {@code AudioStyle}). A style turns an {@link Audio}
 * node's media configuration (its playback signals) into a body view. Styles are
 * injected down the tree via {@code View.audioStyle(AudioStyle)}.
 *
 * <p>The default {@link NativeAudioStyle} contributes no control children — the
 * renderer shows native controls. A custom style returns the app-defined control
 * UI (transport buttons, seek/volume sliders) bound to the configuration's
 * signals; those children become the {@code AUDIO} node's children, so the
 * renderer emits a hidden media element + the custom controls.
 */
public interface AudioStyle {

    /** Build the styled body for {@code config}. */
    View makeBody(Configuration config);

    /**
     * The media configuration of the audio being styled: the playback signals a
     * custom control UI binds to. The source rides the {@code Audio} view itself.
     *
     * @param playing  the play/pause state (writable — a control toggles it)
     * @param position the play position in seconds (writable — a seek slider)
     * @param volume   the volume 0..1 (writable — a volume slider)
     * @param duration the media length in seconds (the seek slider's maximum)
     */
    record Configuration(WritableSignal<Boolean> playing, WritableSignal<Float> position,
                         WritableSignal<Float> volume, float duration) {}
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/** The default audio style: no control children — the renderer shows native
 *  media controls ({@code <audio controls>}); the app supplies only the source. */
public enum NativeAudioStyle implements AudioStyle {

    INSTANCE;

    @Override
    public View makeBody(Configuration config) {
        return env -> new PathlandNode(Components.AUDIO);
    }
}

package com.pathland.view;

import com.pathland.view.signal.WritableSignal;

/**
 * A video style (SwiftUI {@code VideoStyle}). A style turns a {@link Video}
 * node's media configuration into a body view, mirroring {@link AudioStyle}.
 * Injected down the tree via {@code View.videoStyle(VideoStyle)}.
 */
public interface VideoStyle {

    /** Build the styled body for {@code config}. */
    View makeBody(Configuration config);

    /**
     * The media configuration of the video being styled (same shape as
     * {@link AudioStyle.Configuration}); the source rides the {@code Video} view.
     */
    record Configuration(WritableSignal<Boolean> playing, WritableSignal<Float> position,
                         WritableSignal<Float> volume, float duration) {}
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/** The default video style: no control children — native media controls. */
public enum NativeVideoStyle implements VideoStyle {

    INSTANCE;

    @Override
    public View makeBody(Configuration config) {
        return env -> new PathlandNode(Components.VIDEO);
    }
}

package com.pathland.view;

/**
 * A {@link ViewModifier} that scopes an {@link AudioStyle} down the wrapped
 * subtree (SwiftUI {@code .audioStyle}). Applied via
 * {@code view.with(AudioStyleMod.of(style))}; the scope rides the generic
 * environment ({@link Environment#AUDIO_STYLE}).
 */
public final class AudioStyleMod implements ViewModifier {

    private final AudioStyle style;

    private AudioStyleMod(AudioStyle style) {
        this.style = style;
    }

    /** Scope {@code style} down the wrapped subtree. */
    public static AudioStyleMod of(AudioStyle style) {
        return new AudioStyleMod(style);
    }

    @Override
    public View body(View content) {
        return content.environment(Environment.AUDIO_STYLE, style);
    }
}

package com.pathland.view;

/**
 * A {@link ViewModifier} that scopes a {@link VideoStyle} down the wrapped
 * subtree (SwiftUI {@code .videoStyle}). The scope rides the generic environment
 * ({@link Environment#VIDEO_STYLE}).
 */
public final class VideoStyleMod implements ViewModifier {

    private final VideoStyle style;

    private VideoStyleMod(VideoStyle style) {
        this.style = style;
    }

    /** Scope {@code style} down the wrapped subtree. */
    public static VideoStyleMod of(VideoStyle style) {
        return new VideoStyleMod(style);
    }

    @Override
    public View body(View content) {
        return content.environment(Environment.VIDEO_STYLE, style);
    }
}

